from pathlib import Path
import re,sys,subprocess
S=Path(__file__).resolve().parent;R=S.parent.parent;W=R/'.scratch/net-wave4/net-errors'
license='// Copyright 2026 The Chromium Authors\n// Use of this source code is governed by a BSD-style license that can be\n// found in the LICENSE file.\n'
errors=re.findall(r'^NET_ERROR\((\w+),\s*(-?\d+)\)',(S/'net_error_list.h').read_text(),re.M)
file_errors=re.findall(r'^\s*(FILE_\w+)\s*=\s*(-?\d+)',(R/'base/files/file.h').read_text(),re.M)
products={}
if '--check-dir' in sys.argv:
 W=Path(sys.argv[sys.argv.index('--check-dir')+1]).resolve()
 W.mkdir(parents=True,exist_ok=True)
products['net_error_rust_ids.rs']=license+'// Generated by net_error_rust_generate.py; do not edit.\n'+''.join(f'pub const ERR_{k}: i32 = {v};\n' for k,v in errors)+''.join(f'pub const {k}: i32 = {v};\n' for k,v in file_errors)+f'pub const ERR_CERT_BEGIN: i32 = ERR_CERT_COMMON_NAME_INVALID;\n'
products['net_error_rust_names.rs']=license+'// Generated from canonical net_error_list.h.\n'+'pub fn short_name(error: i32) -> Option<&\'static [u8]> {\n    match error {\n        0 => Some(b"OK"),\n'+''.join(f'        {v} => Some(b"ERR_{k}"),\n' for k,v in errors)+'        _ => None,\n    }\n}\n'
# Membership callers need only a boolean, not the complete string-view lookup.
# Keep one byte per error code; canonical values remain the only source of truth.
assert errors and all(int(v)<0 for _,v in errors)
max_error=max(-int(v) for _,v in errors)
known_bytes=[0]*(max_error+1)
for code in [0,*[-int(v) for _,v in errors]]:
 known_bytes[code]=1
products['net_error_rust_names.rs']+='#[rustfmt::skip]\nconst KNOWN_ERROR_BYTES: [u8; '+str(len(known_bytes))+'] = [\n'+''.join('    '+', '.join(map(str,known_bytes[i:i+16]))+',\n' for i in range(0,len(known_bytes),16))+'];\n'
products['net_error_rust_names.rs']+='pub fn defined(error: i32) -> bool {\n    // Wrapping negation keeps every signed input defined; positive values and\n    // i32::MIN become out-of-range indices and never reach the table.\n    let index = error.wrapping_neg() as u32 as usize;\n    index <= '+str(max_error)+' && KNOWN_ERROR_BYTES[index] != 0\n}\n'
products['net_error_rust_enum_checks.h']=license+'// Generated canonical enum drift assertions.\n'+''.join(f'static_assert(base::File::{k} == {v});\n' for k,v in file_errors)+''.join(f'static_assert(ERR_{k} == {v});\n' for k,v in errors)+'constexpr int kNetErrorRustCanonicalCount = 0\n#define NET_ERROR(label, value) + 1\n#include \"net/base/net_error_list.h\"\n#undef NET_ERROR\n;\n'+f'static_assert(kNetErrorRustCanonicalCount == {len(errors)});\n'
for platform,typ in [('win','u32'),('posix','i32')]:
 original=(S/f'net_error_rust_reference_{platform}.cc').read_text()
 # Strip comments and preprocessor guards: duplicate EWOULDBLOCK comparison is harmless in Rust.
 original=re.sub(r'//[^\n]*','',original)
 entries=[];pending=[]
 for token in re.finditer(r"\bcase\s+(\w+)\s*:|\breturn\s+(\w+)\s*;",original):
  if token[1] is not None:pending.append(token[1])
  elif pending:
   for name in pending:entries.append((name,token[2]))
   pending=[]
 constants=[(k,v) for k,v in entries if k not in ['0','ERROR_SUCCESS']]
 struct='WindowsConstants' if platform=='win' else 'PosixConstants'
 products[f'net_error_rust_{platform}_constants.inc']=license+'// Named native constants only; mapping policy lives in Rust.\n'+''.join(f'NET_ERROR_RUST_CONSTANT({k})\n' for k,v in constants)
 products[f'net_error_rust_{platform}.rs']=license+'// Generated named constant layout; Rust owns comparisons and mapping.\nuse super::ids::*;\n#[repr(C)]\n#[derive(Clone, Copy)]\npub struct '+struct+' {\n'+''.join(f'    pub {k.lower()}: {typ},\n' for k,v in constants)+'}\n'+f'pub fn map(error: {typ}, c: &{struct}) -> Option<i32> '+'{\n    if error == 0 { return Some(0); }\n'+''.join(f'    if error == c.{k.lower()} '+'{'+f' return Some({v}); '+'}\n' for k,v in constants)+'    None\n}\n'
 products[f'net_error_rust_{platform}_tests.rs']=license+'// Synthetic named constants exercise every policy case on any host.\n#[test]\nfn mappings_'+platform+'() {\n    use super::*;\n    let c = '+struct+' {\n'+''.join(f'        {k.lower()}: {i+100},\n' for i,(k,v) in enumerate(constants))+'    };\n    assert_eq!(map(0, &c), Some(0));\n'+''.join(f'    assert_eq!(map(c.{k.lower()}, &c), Some({v}));\n' for k,v in constants)+('    let mut c = c;\n    c.ewouldblock = c.eagain;\n    assert_eq!(map(c.eagain, &c), Some(ERR_IO_PENDING));\n' if platform=='posix' else '')+'    assert_eq!(map(1, &c), None);\n'+('    assert_eq!(map(u32::MAX, &c), None);\n' if platform=='win' else '    assert_eq!(map(i32::MIN, &c), None);\n    assert_eq!(map(-1, &c), None);\n')+'}\n'
 products[f'net_error_rust_{platform}.rs']+=f'#[cfg(test)]\ninclude!("net_error_rust_{platform}_tests.rs");\n'
 if platform=='win':
  vendor=R/'third_party/rust/chromium_crates_io/vendor/windows-sys-v0_52/src/Windows/Win32'
  bindings={}
  for module,path in [('foundation',vendor/'Foundation/mod.rs'),('ws',vendor/'Networking/WinSock/mod.rs')]:
   for name,value in re.findall(r'^pub const (\w+): [\w:]+ = (-?\d+)[iu]\d+;',path.read_text(),re.M):
    if name in {k for k,_ in constants}:
     assert name not in bindings,f'ambiguous Windows binding: {name}'
     bindings[name]=(module,int(value))
  assert set(bindings)=={k for k,_ in constants},'missing named Windows binding'
  assert all(0<value<=0xffffffff for _,value in bindings.values())
  def native_expr(name):
   return f'{bindings[name][0]}::{name}'+(' as u32' if bindings[name][0]=='ws' else '')
  guards=''.join(f'const _: () = assert!({native_expr(name)} == {bindings[name][1]}_u32);\n' for name,_ in constants)
  policy=''.join(f'    if error == {native_expr(name)} '+'{'+f' return Some({result}); '+'}\n' for name,result in constants)
  products['net_error_rust_win_native.rs']=license+'// Generated from frozen mapping policy and named Microsoft windows-sys bindings.\nuse super::ids::*;\nuse windows_sys::Win32::{Foundation as foundation, Networking::WinSock as ws};\n'+guards+'pub fn map(error: u32) -> Option<i32> {\n    if error == 0 { return Some(0); }\n'+policy+'    None\n}\n#[cfg(test)]\ninclude!("net_error_rust_win_native_tests.rs");\n'
  products['net_error_rust_win_sdk_checks.h']=license+'// Generated paired SDK/binding drift guards. Rust checks the same values.\n#ifndef NET_BASE_NET_ERROR_RUST_WIN_SDK_CHECKS_H_\n#define NET_BASE_NET_ERROR_RUST_WIN_SDK_CHECKS_H_\n#include <cstdint>\nstatic_assert(ERROR_SUCCESS == 0);\n'+''.join(f'static_assert(static_cast<uint32_t>({name}) == {bindings[name][1]}u);\n' for name,_ in constants)+'#endif\n'
  products['net_error_rust_win_native_tests.rs']=license+'// Actual named bindings must preserve the generic arbitrary-POD mapping.\n#[test]\nfn native_mappings_and_boundaries() {\n    use super::*;\n    let c = super::windows::WindowsConstants {\n'+''.join(f'        {name.lower()}: {native_expr(name)},\n' for name,_ in constants)+'    };\n    for code in (0..=65535).chain([0x7fffffff,0x80000000,u32::MAX]) {\n        assert_eq!(map(code), super::windows::map(code, &c), "{code}");\n    }\n'+''.join(f'    assert_eq!(map({native_expr(name)}), Some({result}));\n' for name,result in constants)+'}\n'
for name,content in products.items():
 dest=S/name
 if '--check' in sys.argv:
  temp=W/name;temp.write_text(content)
  if name.endswith('.h'):subprocess.run([str(Path('D:/RustiumBuild/src/buildtools/win-format/clang-format.exe')),'-i',str(temp)],check=True)
  if name.endswith('.rs'):subprocess.run([str(Path('D:/RustiumBuild/src/third_party/rust-toolchain/bin/rustfmt.exe')),'--edition=2024',str(temp)],check=True)
  assert dest.read_bytes()==temp.read_bytes(),f'stale generated table: {name}'
 else:
  dest.write_text(content)
  if name.endswith('.h'):subprocess.run([str(Path('D:/RustiumBuild/src/buildtools/win-format/clang-format.exe')),'-i',str(dest)],check=True)
  if name.endswith('.rs'):subprocess.run([str(Path('D:/RustiumBuild/src/third_party/rust-toolchain/bin/rustfmt.exe')),'--edition=2024',str(dest)],check=True)
print('Generated/check: ',len(products),'table/constant/test files')
